import { useStore } from '~/app/store/store';
import { AppParams, SuperAppEncData } from '~/entities/super-app/model/types';
import { useApiSignVerifyReq } from '~/entities/intro/api/use-api-sign-verify-req-mutation';
import { useApiSignVerifyRes } from '~/entities/intro/api/use-api-sign-verify-res-mutation';
import { devSnackBar } from '~/shared/lib/toast';

export const RsaOaep = () => {
  const { mutateAsync: apiSignVerifyRes } = useApiSignVerifyRes();
  const { mutateAsync: apiSignVerifyReq } = useApiSignVerifyReq();

  const encryptText = async (data: SuperAppEncData): Promise<SuperAppEncData> => {
    await devSnackBar('RSA-OAEP 암호화 시작...', 700);
    const ret: SuperAppEncData = await apiSignVerifyRes(data);
    await devSnackBar('RSA-OAEP 암호화 완료', 700);
    return ret as SuperAppEncData;
  };

  const decryptText = async (data: SuperAppEncData) => {
    if (!data?.encData || !data?.signature) return {} as SuperAppEncData;
    await devSnackBar('RSA-OAEP 복호화 시작...', 700);
    const decText = await apiSignVerifyReq({
      encData: data.encData,
      signature: data.signature,
      userId: data.userId,
      superAppCallback: data.superAppCallback,
    });
    if (!decText.userCI || !decText.userId || !decText.account || !decText.sid) {
      throw new Error('userCI, userId, account, sid is required');
    }

    const retData: SuperAppEncData = {
      ...data,
      ...decText,
      ci: decText.userCI,
      cstmrNo: decText.userId,
      acnutno: decText.account,
      encData: null,
      signature: null,
      sid: decText.sid,
    };

    if (!retData?.cstmrNo) {
      throw new Error('cstmrNo is required');
    }
    const decData: AppParams = { ...retData, cstmrNo: retData.cstmrNo, sid: retData.sid };

    useStore.getState().superAppSlice.setDecData({ ...decData });
    await devSnackBar('RSA-OAEP 복호화 완료', 500);
    return retData;
  };

  return { encryptText, decryptText };
};
