import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { SuperAppEncData, SuperAppParams } from '~/entities/super-app/model/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';

const apiSignVerifyRes = (data: SuperAppParams) => {
  return resultify(axios.post<SuperAppEncData>(`${API_URLS.signVerifyRes}`, data));
};

export const useApiSignVerifyRes = (options?: MutationOptions<SuperAppParams, CBDCAxiosError, SuperAppEncData>) => {
  const mutation = useMutation<SuperAppEncData, CBDCAxiosError, SuperAppParams>({
    ...options,
    mutationFn: (data: SuperAppParams) => apiSignVerifyRes(data),
  });

  return {
    ...mutation,
  };
};
